from dataclasses import dataclass

# ---- Write side: owns invariants ----
@dataclass(frozen=True)
class PlaceOrder:
    order_id: str
    customer_id: str
    amount_cents: int
    idempotency_key: str

class OrderAggregate:
    def __init__(self):
        self.placed = False
        self.version = 0

    def handle(self, cmd: PlaceOrder):
        # Business rule lives HERE, not in the read model.
        if self.placed:
            raise ValueError("duplicate order")
        if cmd.amount_cents <= 0:
            raise ValueError("invalid amount")
        self.placed = True
        self.version += 1
        # Durable fact. Write store + outbox commit atomically.
        return {
            "event_id": cmd.idempotency_key,  # dedupe key downstream
            "type": "OrderPlaced.v2",
            "order_id": cmd.order_id,
            "customer_id": cmd.customer_id,
            "amount_cents": cmd.amount_cents,
            "version": self.version,
        }

# ---- Projection: must be idempotent + version-aware ----
class OrderSummaryProjector:
    def __init__(self, views):
        self.views = views  # e.g. search index + detail store
        self.seen = set()   # in reality: unique constraint on event_id

    def apply(self, event):
        if event["event_id"] in self.seen:
            return  # at-least-once delivery: duplicates are normal
        if event["type"] == "OrderPlaced.v1":
            event = self._upgrade_v1(event)
        assert event["type"] == "OrderPlaced.v2"
        # Upsert, never blind insert. Replays must converge.
        self.views["detail"].upsert(event["order_id"], event)
        self.views["by_customer"].upsert(event["customer_id"], event)
        self.seen.add(event["event_id"])

    def _upgrade_v1(self, e):
        e = dict(e); e["type"] = "OrderPlaced.v2"
        e.setdefault("amount_cents", 0)
        return e

# ---- Read side: shaped for screens, never validates ----
class OrderQueries:
    def __init__(self, views, write_fallback):
        self.views = views
        self.write_fallback = write_fallback

    def get_order(self, order_id, min_version=None):
        doc = self.views["detail"].get(order_id)
        # Close the read-your-write gap for just-written keys.
        # Trade-off: one narrow bypass, not general read-from-write.
        if doc is None or (min_version and doc["version"] < min_version):
            doc = self.write_fallback.get(order_id)
        return doc

    def orders_for_customer(self, customer_id):
        # Single-key lookup. No joins at request time because the
        # projector already denormalized. Stale by lag SLA, e.g. <2s p99.
        return self.views["by_customer"].query(customer_id)
